const {crypto,fulfill}=require('../_core');
module.exports=async(req,res)=>{if(req.method!=='POST')return res.status(405).end();const raw=Buffer.isBuffer(req.body)?req.body:Buffer.from(JSON.stringify(req.body||{}));const sig=req.headers['x-paystack-signature']||'';const expected=crypto.createHmac('sha512',process.env.PAYSTACK_SECRET_KEY).update(raw).digest('hex');if(sig.length!==expected.length||!crypto.timingSafeEqual(Buffer.from(sig),Buffer.from(expected)))return res.status(401).end();let event;try{event=JSON.parse(raw.toString());}catch{return res.status(400).end();}if(event.event!=='charge.success'||!event.data?.reference)return res.status(200).end();try{await fulfill(event.data.reference);return res.status(200).end();}catch(e){console.error('Webhook fulfillment failed',e);return res.status(500).end();}};
